CREATE TABLE app_users(id BIGSERIAL PRIMARY KEY,name VARCHAR(80) NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE mood_entries(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,mood VARCHAR(20) NOT NULL,note VARCHAR(500),energy INTEGER NOT NULL CHECK(energy BETWEEN 1 AND 5),stress INTEGER NOT NULL CHECK(stress BETWEEN 1 AND 5),created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_mood_user_date ON mood_entries(user_id,created_at DESC);
CREATE TABLE journal_entries(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,title VARCHAR(120) NOT NULL,content TEXT NOT NULL,mood VARCHAR(20),created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_journal_user_date ON journal_entries(user_id,created_at DESC);
